command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="1ceb0699c2c3162eae50e7392cf3fab102019e7c"
$branch="work/shell-provider-copyin-20261008"
Set-Location -LiteralPath $repo
& git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main changed"}
$ref="refs/remotes/origin/"+$branch
& git show-ref --verify --quiet $ref
if($LASTEXITCODE -ne 0){throw "work branch missing"}
$branchHead=(& git rev-parse $ref).Trim()
if($branchHead -ne $main){throw "branch diverges from accepted main"}
& git merge-base --is-ancestor $branchHead $main
if($LASTEXITCODE -ne 0){throw "work branch not merged"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "work branch deletion failed"}
& git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "post-delete fetch failed"}
& git show-ref --verify --quiet $ref
if($LASTEXITCODE -eq 0){throw "deleted branch remains"}
Write-Host "SHELL_PROVIDER_COPYIN_WORK_BRANCH_CLEANUP=PASS"
